function rememberEditor(){programmeEditor.undo.push(programmeEditor.ids.slice());if(programmeEditor.undo.length>30)programmeEditor.undo.shift();}
function moveEditor(id,to,remember=true){const editor=programmeEditor;if(!editor||editorStale()||editor.busy)return;const from=editor.ids.indexOf(id);to=Math.max(0,Math.min(editor.ids.length-1,to));if(from<0||from===to)return;if(remember)rememberEditor();editor.ids.splice(to,0,editor.ids.splice(from,1)[0]);paintEditor();}
function undoEditor(){if(programmeEditor?.undo.length&&!editorStale()){programmeEditor.ids=programmeEditor.undo.pop();paintEditor();}}
function sortExperienceOrder(mode){const e=programmeEditor;if(!e||editorStale()||e.busy)return;rememberEditor();if(mode==="source")e.ids=e.original.slice();else if(mode==="reverse")e.ids.reverse();else e.ids.sort((a,b)=>{const first=orderItem(a),second=orderItem(b);if(mode==="ready")return Number(second.ready)-Number(first.ready);if(mode==="episode")return (episodeNumber(first.title)??Infinity)-(episodeNumber(second.title)??Infinity)||0;return first.title.localeCompare(second.title,"ru",{numeric:true});});paintEditor();}
function paintEditor(){
    const e=programmeEditor;if(!e||!e.ui.dialog.open)return;const list=byId("experienceOrderList"),focused=document.activeElement;if(!list)return;
    e.ids.forEach((id,index)=>{const row=e.rows.get(id);row.querySelector(".order-number").textContent=index+1;row.querySelector("input").value=index+1;row.querySelector(".order-handle").setAttribute("aria-label",`Позиция ${index+1} из ${e.ids.length}: ${orderItem(id).title}`);if(list.children[index]!==row)list.insertBefore(row,list.children[index]||null);});
    if(focused?.isConnected&&document.activeElement!==focused)focused.focus({preventScroll:true});
    if(e.drag&&!e.drag.handle.hasPointerCapture(e.drag.pointerId))e.drag.handle.setPointerCapture(e.drag.pointerId);
    const stale=editorStale();e.ui.message.textContent=stale?"Программа изменилась. Ваш черновик сохранён на экране; закройте редактор и откройте свежий список.":`${e.ids.length} элементов · изменения ещё не сохранены`;
    byId("experienceOrderSave").disabled=stale||e.busy;byId("experienceOrderUndo").disabled=!e.undo.length||stale||e.busy;
    const currentId=state.items[state.currentIndex]?.videoId,index=e.ids.indexOf(currentId);const nextId=index>=0?e.ids[index+1]:e.ids[0];
    byId("experienceOrderNext").textContent=(index>=0?"После текущего: ":"Первым будет: ")+(nextId!==undefined?orderItem(nextId).title:"остановка в конце плейлиста");
}
function startOrderPointer(event,id,handle){const e=programmeEditor;if(!e||editorStale()||e.busy||event.button!==0)return;event.preventDefault();e.drag={id,pointerId:event.pointerId,handle,original:e.ids.slice(),y:event.clientY,raf:null};handle.setPointerCapture(event.pointerId);e.rows.get(id).classList.add("dragging");const scroll=()=>{if(!programmeEditor?.drag)return;const body=e.ui.body,rect=body.getBoundingClientRect(),y=e.drag.y;const speed=y<rect.top+65?-12:y>rect.bottom-65?12:0;if(speed){body.scrollTop+=speed;reorderAtPoint(y);}e.drag.raf=requestAnimationFrame(scroll);};e.drag.raf=requestAnimationFrame(scroll);}
function reorderAtPoint(y){const e=programmeEditor;if(!e?.drag)return;const candidates=[...e.rows.entries()].filter(([id])=>id!==e.drag.id);let best=null,distance=Infinity;for(const [id,row] of candidates){const rect=row.getBoundingClientRect(),d=Math.abs(y-(rect.top+rect.height/2));if(d<distance){distance=d;best=id;}}if(best!==null){const rect=e.rows.get(best).getBoundingClientRect();if(y>=rect.top&&y<=rect.bottom)moveEditor(e.drag.id,e.ids.indexOf(best),false);}}
