function finishOrderPointer(cancelled){const e=programmeEditor,drag=e?.drag;if(!drag)return;cancelAnimationFrame(drag.raf);e.rows.get(drag.id).classList.remove("dragging");e.drag=null;if(drag.handle.hasPointerCapture(drag.pointerId))drag.handle.releasePointerCapture(drag.pointerId);if(cancelled)e.ids=drag.original;else if(JSON.stringify(drag.original)!==JSON.stringify(e.ids))e.undo.push(drag.original);paintEditor();}
