function updateVideoProgress(row,item){const progress=programmeVideo(item.videoId),current=state.items[state.currentIndex]?.videoId===item.videoId,position=current?state.positionMs:progress?.positionMs||0,duration=current?state.durationMs:progress?.durationMs||item.durationSeconds*1000;const fill=row.querySelector(".watch-progress span"),label=row.querySelector(".watch-progress-label");if(fill)fill.style.width=Math.max(0,Math.min(100,100*position/(duration||Infinity)))+"%";if(label)label.textContent=`${progress?.favorite?"★ · ":""}${progress?.status==="WATCHED"?"Просмотрено":position>0?"Продолжить с "+resumeTime(position):"Ещё не смотрели"}${progress?.bookmarks?.length?" · закладок: "+progress.bookmarks.length:""}`;}
