function renderVideoPreview(){
    const p=videoPreview,body=byId("singlePreviewBody");if(!body)return;body.hidden=p?.status!=="COMPLETE";byId("singlePreviewMessage").textContent=p?.status==="LOADING"?"Получаем название и доступное качество. Просмотр не запускается.":p?.status==="ERROR"?"Не удалось получить видео: "+experienceError(Error(p.error||"Ошибка источника")):p?.status==="CANCELLED"?"Предпросмотр отменён.":"";byId("singlePreviewRetry").hidden=!p||p.status!=="ERROR";if(p?.status!=="COMPLETE")return;
    const cover=byId("singlePreviewCover");cover.replaceChildren();cover.className="";appendVideoThumbnail(cover,p.videoId,p.title);byId("singlePreviewTitle").textContent=p.title||"Название ещё не получено";byId("singlePreviewDuration").textContent=formatDuration(p.durationSeconds);
    const quality=byId("singlePreviewQuality");quality.replaceChildren();for(const q of p.qualities||[]){const option=exNode("option","",`${q.height}p${q.sizeBytes!=null?" · около "+storageSize(q.sizeBytes):" · размер неизвестен"}`);option.value=q.id;quality.append(option);}const savedItem=programmeItem(p.videoId),savedReady=!!savedItem&&videoReady(savedItem);quality.disabled=savedReady||!quality.options.length;quality.closest("label").hidden=savedReady;byId("singleSavedFileHint").hidden=!savedReady;byId("singleSavedFileHint").textContent=savedReady?"Уже скачано: будет использован сохранённый файл. Качество готового файла не меняется.":"";
    selectedStorageOptions(byId("singlePreviewStorage"));const target=byId("singlePreviewGroup");target.replaceChildren();for(const [id,name] of [["","Отдельное видео"],["__new","Новый плейлист"],...(programmeData()?.groups||state.groups||[]).map(g=>[g.id,g.name])]){const o=exNode("option","",name);o.value=id;target.append(o);}byId("singleNewGroupLabel").hidden=true;
    byId("singleWatchSave").disabled=!quality.options.length;byId("singleDownloadLater").disabled=!quality.options.length;byId("singleApplyRetry").hidden=true;if(familyPage==="add")byId("singleVideoConfirm").scrollIntoView({block:"start"});
}
async function applySingleVideo(action,retry=false){
    if(videoPreviewBusy||!videoPreview||videoPreview.status!=="COMPLETE")return;
    if(!retry&&videoPreviewVersion!==state.queueVersion){byId("singlePreviewMessage").textContent="Программа изменилась. Проверьте назначение и нажмите действие ещё раз.";videoPreviewVersion=state.queueVersion;return;}
    const current=state.items[state.currentIndex];if(!retry&&action==="WATCH_SAVE"&&current&&state.intent!=="STOP"&&!confirm(`Начать «${videoPreview.title}» сейчас? Текущий ролик «${current.title||"Видео"}» будет заменён; его позиция сохранится.`))return;
    videoPreviewBusy=true;document.querySelectorAll(".single-actions button").forEach(b=>b.disabled=true);
    try{let payload;if(retry)payload=singleApplyReceipt;else{const target=byId("singlePreviewGroup").value,newName=byId("singleNewGroupName").value.trim();if(target==="__new"&&!newName)throw Error("Введите название нового плейлиста");const storage=action==="ADD"?{}:await useStorage(byId("singlePreviewStorage").value);payload={previewId:videoPreview.previewId,action,queueVersion:videoPreviewVersion,...storage,idempotencyKey:commandKey(),...(action!=="ADD"?{qualityId:byId("singlePreviewQuality").value}:{}),...(target==="__new"?{groupName:newName}:target?{groupId:target}:{})};singleApplyReceipt=payload;}
        const result=await perform("single-experience-"+payload.idempotencyKey,"/api/video/apply",payload);const failedPreparation=result.stage==="SAVED"&&payload.action!=="ADD";
        byId("singlePreviewMessage").textContent=failedPreparation?"Видео сохранено в программе, но подготовка не началась. "+experienceError(Error(result.error||"Проверьте сеть и хранилище")):result.stage==="PLAYING"?"Просмотр запущен. Видео сохраняется во время просмотра.":result.stage==="PREPARING"?"Видео в программе и поставлено на загрузку. Просмотр не запущен.":"Видео добавлено в программу. Просмотр не запущен.";byId("singleApplyRetry").hidden=!failedPreparation;
        if(!failedPreparation){exMessage(byId("singlePreviewMessage").textContent);showFamilyPage(result.stage==="PLAYING"?"remote":result.stage==="PREPARING"?"downloads":"library");importSingleLink="";importStep=1;}
    }catch(error){byId("singlePreviewMessage").textContent=experienceError(error);}finally{videoPreviewBusy=false;document.querySelectorAll(".single-actions button").forEach(b=>b.disabled=false);}
}
function initializeVideoExperience(){
    const container=byId("singleVideoConfirm");container.replaceChildren(familyTemplate('<h2>Видео перед добавлением</h2><p id="singleVideoLink" class="muted small"></p><p id="singlePreviewMessage" class="message" role="status"></p><button id="singlePreviewRetry" type="button" class="secondary" hidden>Повторить предпросмотр</button><div id="singlePreviewBody" hidden><div class="video-preview-card"><div id="singlePreviewCover"></div><div><h3 id="singlePreviewTitle"></h3><p id="singlePreviewDuration" class="muted"></p></div></div><p id="singleSavedFileHint" class="notice small" hidden></p><div class="quality-row"><label>Качество<select id="singlePreviewQuality"></select></label><label>Хранилище<select id="singlePreviewStorage"></select></label></div><label>Добавить в<select id="singlePreviewGroup"></select></label><label id="singleNewGroupLabel" hidden>Название нового плейлиста<input id="singleNewGroupName" maxlength="120"></label><div class="single-actions"><button id="singleWatchSave" type="button">Смотреть и сохранять<small>Начать сейчас; текущий ролик будет заменён</small></button><button id="singleDownloadLater" type="button" class="secondary">Скачать для просмотра позже<small>Подготовить целиком без запуска</small></button><button id="singleAddOnly" type="button" class="secondary">Добавить в программу<small>Сохранить выбор без загрузки</small></button></div></div><button id="singleApplyRetry" type="button" hidden>Повторить подготовку сохранённого видео</button><button id="singleVideoBack" type="button" class="secondary">Назад / отменить</button>'));
    byId("singleWatchSave").addEventListener("click",()=>run(()=>applySingleVideo("WATCH_SAVE")));byId("singleDownloadLater").addEventListener("click",()=>run(()=>applySingleVideo("DOWNLOAD_LATER")));byId("singleAddOnly").addEventListener("click",()=>run(()=>applySingleVideo("ADD")));byId("singleApplyRetry").addEventListener("click",()=>run(()=>applySingleVideo(singleApplyReceipt?.action,true)));byId("singleVideoBack").addEventListener("click",()=>run(async()=>{await cancelVideoPreview();importSingleLink="";importStep=1;syncImportFlow();}));byId("singlePreviewRetry").addEventListener("click",()=>run(()=>beginVideoPreview(importSingleLink)));byId("singlePreviewGroup").addEventListener("change",()=>byId("singleNewGroupLabel").hidden=byId("singlePreviewGroup").value!=="__new");
}
